#include <iostream>
#include <future>
#include <thread>

void producer(std::promise<int>& p) {
    p.set_value(100);   // 把结果放入通道；若抛异常也会被 future 重抛
}

int main() {
    std::promise<int> p;
    std::future<int> f = p.get_future();
    std::thread t(producer, std::ref(p));
    t.join();
    std::cout << "value=" << f.get();   // 阻塞取通道里的值
}
